class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map(); // first = least recently used
  }

  get(key) {
    if (!this.map.has(key)) return -1;
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value); // now the most recent
    return value;
  }

  put(key, value) {
    if (this.map.has(key)) this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.capacity) {
      this.map.delete(this.map.keys().next().value);
    }
  }
}

class MyPromise {
  constructor(executor) {
    this.state = 'pending';
    this.value = undefined;
    this.callbacks = [];
    let called = false; // resolve/reject work only once
    const settle = (state, value) => {
      if (this.state !== 'pending') return;
      this.state = state;
      this.value = value;
      this.callbacks.forEach((cb) => cb());
      this.callbacks = [];
    };
    const resolve = (x) => {
      if (called) return;
      called = true;
      adopt(x);
    };
    const adopt = (x) => {
      if (x === this) return settle('rejected', new TypeError('A promise cannot resolve to itself'));
      if (x !== null && (typeof x === 'object' || typeof x === 'function')) {
        let then;
        try { then = x.then; } catch (e) { return settle('rejected', e); }
        if (typeof then === 'function') {
          let done = false;
          try {
            then.call(x, (y) => { if (!done) { done = true; adopt(y); } }, (r) => { if (!done) { done = true; settle('rejected', r); } });
          } catch (e) {
            if (!done) { done = true; settle('rejected', e); }
          }
          return;
        }
      }
      settle('fulfilled', x);
    };
    const reject = (r) => {
      if (called) return;
      called = true;
      settle('rejected', r);
    };
    try { executor(resolve, reject); } catch (e) { reject(e); }
  }

  then(onFulfilled, onRejected) {
    return new MyPromise((resolve, reject) => {
      const run = () => queueMicrotask(() => {
        const handler = this.state === 'fulfilled' ? onFulfilled : onRejected;
        if (typeof handler !== 'function') {
          return this.state === 'fulfilled' ? resolve(this.value) : reject(this.value);
        }
        try { resolve(handler(this.value)); } catch (e) { reject(e); }
      });
      if (this.state === 'pending') this.callbacks.push(run);
      else run();
    });
  }

  catch(onRejected) {
    return this.then(undefined, onRejected);
  }

  finally(fn) {
    return this.then(
      (v) => MyPromise.resolve(fn()).then(() => v),
      (e) => MyPromise.resolve(fn()).then(() => { throw e; }),
    );
  }

  static resolve(v) {
    return v instanceof MyPromise ? v : new MyPromise((r) => r(v));
  }
}

function promiseAll(iterable) {
  const items = [...iterable];
  return new Promise((resolve, reject) => {
    if (items.length === 0) return resolve([]);
    const results = new Array(items.length);
    let done = 0;
    items.forEach((item, i) => {
      Promise.resolve(item).then((v) => {
        results[i] = v;
        if (++done === items.length) resolve(results);
      }, reject);
    });
  });
}

function promiseRace(iterable) {
  return new Promise((resolve, reject) => {
    for (const item of iterable) Promise.resolve(item).then(resolve, reject);
  });
}

function promiseAllSettled(iterable) {
  const items = [...iterable];
  return new Promise((resolve) => {
    if (items.length === 0) return resolve([]);
    const results = new Array(items.length);
    let done = 0;
    const finish = (i, r) => {
      results[i] = r;
      if (++done === items.length) resolve(results);
    };
    items.forEach((item, i) => {
      Promise.resolve(item).then(
        (value) => finish(i, { status: 'fulfilled', value }),
        (reason) => finish(i, { status: 'rejected', reason }),
      );
    });
  });
}

function promiseAny(iterable) {
  const items = [...iterable];
  return new Promise((resolve, reject) => {
    if (items.length === 0) return reject(new AggregateError([], 'All promises were rejected'));
    const reasons = new Array(items.length);
    let failed = 0;
    items.forEach((item, i) => {
      Promise.resolve(item).then(resolve, (r) => {
        reasons[i] = r;
        if (++failed === items.length) reject(new AggregateError(reasons, 'All promises were rejected'));
      });
    });
  });
}

async function runWithConcurrency(tasks, limit) {
  const results = new Array(tasks.length);
  let next = 0;
  const worker = async () => {
    while (next < tasks.length) {
      const i = next++; // safe: no await between read and increment
      results[i] = await tasks[i]();
    }
  };
  const count = Math.max(1, Math.min(limit, tasks.length));
  await Promise.all(Array.from({ length: count }, worker));
  return results;
}

function deepEqual(a, b) {
  if (Object.is(a, b)) return true;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) return false;
  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false;

  if (a instanceof Date) return a.getTime() === b.getTime();
  if (a instanceof RegExp) return a.source === b.source && a.flags === b.flags;

  if (a instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [k, v] of a) if (!b.has(k) || !deepEqual(v, b.get(k))) return false;
    return true;
  }
  if (a instanceof Set) {
    if (a.size !== b.size) return false;
    for (const v of a) {
      if (b.has(v)) continue;
      let found = false;
      for (const w of b) if (deepEqual(v, w)) { found = true; break; }
      if (!found) return false;
    }
    return true;
  }

  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
    if (!deepEqual(a[k], b[k])) return false;
  }
  return true;
}

