const steps = {
  *filter(src, fn) { for (const x of src) if (fn(x)) yield x; },
  *map(src, fn) { for (const x of src) yield fn(x); },
  *take(src, n) {
    if (n <= 0) return;
    let count = 0;
    for (const x of src) {
      yield x;
      if (++count >= n) return;
    }
  },
  *sort(src, cmp) { yield* [...src].sort(cmp); },
};

function chain(data) {
  const ops = [];
  const api = {
    filter(fn) { ops.push(['filter', fn]); return api; },
    map(fn) { ops.push(['map', fn]); return api; },
    sort(cmp) { ops.push(['sort', cmp]); return api; },
    take(n) { ops.push(['take', n]); return api; },
    value() {
      let seq = data;
      for (const [type, arg] of ops) seq = steps[type](seq, arg);
      return [...seq];
    },
  };
  return api;
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

class TimeoutError extends Error {
  constructor(message = 'Timed out') {
    super(message);
    this.name = 'TimeoutError';
  }
}

function withTimeout(promise, ms, options = {}) {
  const hasFallback = 'fallback' in options;
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      if (hasFallback) resolve(options.fallback);
      else reject(new TimeoutError('Timed out after ' + ms + 'ms'));
    }, ms);
    Promise.resolve(promise).then(
      (value) => { clearTimeout(timer); resolve(value); },
      (error) => { clearTimeout(timer); reject(error); },
    );
  });
}

class CircuitOpenError extends Error {
  constructor(message = 'Circuit is open') {
    super(message);
    this.name = 'CircuitOpenError';
  }
}

class CircuitBreaker {
  constructor(fn, { failureThreshold = 3, cooldown = 1000 } = {}) {
    this.fn = fn;
    this.failureThreshold = failureThreshold;
    this.cooldown = cooldown;
    this.state = 'CLOSED';
    this.failures = 0;
    this.openedAt = 0;
    this.trial = false;
  }

  async call(...args) {
    if (this.state === 'OPEN' && Date.now() - this.openedAt >= this.cooldown) this.state = 'HALF_OPEN';
    if (this.state === 'OPEN' || (this.state === 'HALF_OPEN' && this.trial)) {
      throw new CircuitOpenError();
    }
    const isTrial = this.state === 'HALF_OPEN';
    if (isTrial) this.trial = true;
    try {
      const result = await this.fn(...args);
      this.failures = 0;
      this.state = 'CLOSED';
      return result;
    } catch (err) {
      if (isTrial || ++this.failures >= this.failureThreshold) {
        this.state = 'OPEN';
        this.openedAt = Date.now();
      }
      throw err;
    } finally {
      if (isTrial) this.trial = false;
    }
  }

  reset() {
    this.state = 'CLOSED';
    this.failures = 0;
    this.trial = false;
  }
}

