class Stopwatch {
  constructor({ now = () => Date.now() } = {}) {
    this.now = now;
    this.reset();
  }

  start() {
    if (this.running) return;
    this.startedAt = this.now();
    this.running = true;
  }

  pause() {
    if (!this.running) return;
    this.banked += this.now() - this.startedAt;
    this.running = false;
  }

  reset() {
    this.running = false;
    this.startedAt = 0;
    this.banked = 0;
    this.laps = [];
    this.lastLapAt = 0;
  }

  getElapsed() {
    return this.banked + (this.running ? this.now() - this.startedAt : 0);
  }

  lap() {
    const total = this.getElapsed();
    const lap = { lap: this.laps.length + 1, split: total - this.lastLapAt, total };
    this.lastLapAt = total;
    this.laps.push(lap);
    return lap;
  }

  getLaps() {
    return this.laps.map((l) => ({ ...l }));
  }

  onTick(cb, every = 100) {
    const id = setInterval(() => {
      if (this.running) cb(this.getElapsed());
    }, every);
    return () => clearInterval(id);
  }
}

function hash(str) {
  let h = 2166136261; // FNV-1a offset basis
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  // final mix (from MurmurHash3) spreads similar strings across the ring
  h ^= h >>> 16;
  h = Math.imul(h, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

class ConsistentHashing {
  constructor({ vnodes = 150 } = {}) {
    this.vnodes = vnodes;
    this.ring = []; // sorted by pos
    this.servers = new Set();
  }

  get size() {
    return this.ring.length;
  }

  addServer(name) {
    if (this.servers.has(name)) return;
    this.servers.add(name);
    for (let i = 0; i < this.vnodes; i++) this.ring.push({ pos: hash(name + '#' + i), server: name });
    this.ring.sort((a, b) => a.pos - b.pos);
  }

  removeServer(name) {
    if (!this.servers.delete(name)) return;
    this.ring = this.ring.filter((m) => m.server !== name);
  }

  getServer(key) {
    if (this.ring.length === 0) return null;
    const h = hash(String(key));
    let lo = 0;
    let hi = this.ring.length; // first index with pos >= h
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this.ring[mid].pos < h) lo = mid + 1;
      else hi = mid;
    }
    return this.ring[lo === this.ring.length ? 0 : lo].server;
  }
}
